{
  "schemaVersion": "0.2",
  "slug": "processing-placeholder",
  "name": "ProcessingPlaceholder",
  "status": "experimental",
  "purpose": "Centered busy placeholder with spinner, copy, optional thumbnail, and action.",
  "scenarios": [
    "Queued / processing job detail while AI work runs."
  ],
  "props": {
    "title": {
      "type": "string",
      "required": true,
      "description": "Primary busy message."
    },
    "description": {
      "type": "string",
      "required": false,
      "description": "Supporting message."
    },
    "thumbnailSrc": {
      "type": "string",
      "required": false,
      "description": "Optional source thumbnail while processing."
    },
    "thumbnailAlt": {
      "type": "string",
      "required": false,
      "description": "Alt text for the thumbnail."
    },
    "spinnerLabel": {
      "type": "string",
      "required": false,
      "description": "Accessible spinner label."
    },
    "action": {
      "type": "node",
      "required": false,
      "description": "Optional action. Vue slot: action."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "busy",
      "description": "Indeterminate processing state."
    }
  ],
  "composition": {
    "allowedParents": [
      "workspace-split",
      "card",
      "stack",
      "page",
      "app-shell"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for empty data — use EmptyState.",
    "Do not use for determinate progress — use Progress / LoadingBar."
  ],
  "a11y": {
    "role": "status",
    "keyboard": [],
    "focus": "Decorative; spinner carries aria-label.",
    "labeling": "Title and spinner label communicate busy state.",
    "wcag": [
      "4.1.3"
    ]
  },
  "responsive": {
    "strategy": "Centered column.",
    "breakpoints": {
      "compact": "Default.",
      "medium": "Default.",
      "large": "Default."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "processing-placeholder",
    "states": [
      "busy"
    ],
    "intents": [
      "indicate-busy"
    ]
  }
}

import type { ReactNode } from 'react'
import { Spinner } from '../spinner/Spinner.js'
import './styles.css'

export interface ProcessingPlaceholderProps {
  title: string
  description?: string
  thumbnailSrc?: string
  thumbnailAlt?: string
  spinnerLabel?: string
  action?: ReactNode
  className?: string
}

export function ProcessingPlaceholder({
  title,
  description,
  thumbnailSrc,
  thumbnailAlt = '',
  spinnerLabel = 'Processing',
  action,
  className,
}: ProcessingPlaceholderProps) {
  const classes = ['cu-processing-placeholder', className].filter(Boolean).join(' ')
  return (
    <div
      className={classes}
      role="status"
      aria-live="polite"
      data-ai-role="processing-placeholder"
      data-ai-intent="indicate-busy"
      data-ai-state="busy"
    >
      <Spinner size="lg" label={spinnerLabel} />
      <p className="cu-processing-placeholder__title">{title}</p>
      {description ? <p className="cu-processing-placeholder__description">{description}</p> : null}
      {thumbnailSrc ? (
        <img
          className="cu-processing-placeholder__thumb"
          src={thumbnailSrc}
          alt={thumbnailAlt}
        />
      ) : null}
      {action ? <div className="cu-processing-placeholder__action">{action}</div> : null}
    </div>
  )
}

.cu-processing-placeholder {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--cu-space-3);
  padding-block: var(--cu-space-6, var(--cu-space-3));
  padding-inline: var(--cu-space-5, var(--cu-space-3));
  text-align: center;
  color: var(--cu-color-fg-default);
}

.cu-processing-placeholder__title {
  margin: 0;
  font-size: var(--cu-typography-size-heading-3, 1.125rem);
  font-weight: var(--cu-typography-weight-semibold, 600);
  letter-spacing: var(--cu-typography-tracking-tight, -0.022em);
  line-height: var(--cu-typography-line-height-snug, 1.25);
}

.cu-processing-placeholder__description {
  margin: 0;
  max-inline-size: 28rem;
  font-size: var(--cu-typography-size-body, 0.9375rem);
  line-height: var(--cu-typography-line-height-body, 1.5);
  color: var(--cu-color-fg-muted, color-mix(in srgb, var(--cu-color-fg-default) 72%, transparent));
}

.cu-processing-placeholder__thumb {
  display: block;
  max-inline-size: 15rem;
  max-block-size: 10rem;
  inline-size: auto;
  block-size: auto;
  object-fit: contain;
  border-radius: var(--cu-radius-md);
  border: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(--cu-color-background-subtle, var(--cu-color-background-default));
}

.cu-processing-placeholder__action {
  margin-block-start: var(--cu-space-1);
}
